insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_96_v1'
from (values
('127.749.d.1.A',3,'A Firefighter II student practices calling for backup on the radio and logging the call on a computer. This is applying:','["protocols for managing emergencies using radio equipment and computers", "ignoring protocols", "guessing", "avoiding technology"]'::jsonb,0,'Radio and computers support emergency management.','original'),
('127.749.d.1.A',4,'Which tool helps a dispatcher record unit status during a large emergency?','["a cookbook", "a computer-aided dispatch system", "a calendar poster", "a paper airplane"]'::jsonb,1,'CAD tracks units and calls.','original'),
('127.749.d.1.B',3,'A fire officer builds a spreadsheet of hydrant flow tests and writes a summary report in a word processor. This demonstrates:','["unrelated tasks", "hiding data", "word-processing and spreadsheet use in fire management", "avoiding software"]'::jsonb,2,'Software supports records and analysis.','original'),
('127.749.d.1.B',4,'A fire chief wants to compare response times over a year. The best software to organize the numbers is a:','["game", "photo editor", "slide show only", "spreadsheet"]'::jsonb,3,'Spreadsheets organize and calculate data.','original'),
('127.749.d.2.A',3,'Engine company members learn the steps to follow when an alarm comes in for a kitchen fire. This is identifying:','["response procedures to emergency incidents", "unrelated chores", "only meals", "only paperwork"]'::jsonb,0,'Procedures guide response.','original'),
('127.749.d.2.A',4,'A written response procedure for emergency incidents helps crews by:','["adding confusion", "providing consistent steps to follow under stress", "delaying response", "replacing training"]'::jsonb,1,'Procedures reduce errors.','original'),
('127.749.d.2.B',3,'In a training drill, a crew responds to a simulated apartment fire, following their written steps. This is:','["random action", "ignoring steps", "applying response procedures in a simulation", "skipping practice"]'::jsonb,2,'Simulations rehearse procedures.','original'),
('127.749.d.2.B',4,'The main value of simulated emergency drills is that they:','["cause injury", "replace real calls", "remove procedures", "let crews practice procedures safely before real calls"]'::jsonb,3,'Practice builds skill.','original'),
('127.749.d.3.A',3,'A stove grease fire, a paper fire and an energized panel fire fall into different:','["classes of fire for portable extinguisher selection", "school classes", "vehicle classes", "rank classes"]'::jsonb,0,'Fire classes determine the right agent.','original'),
('127.749.d.3.A',4,'A fire involving ordinary combustibles such as wood and paper is a:','["Class B fire", "Class A fire", "Class C fire", "Class K fire"]'::jsonb,1,'Class A = ordinary combustibles.','original'),
('127.749.d.3.B',3,'A firefighter selects a carbon dioxide extinguisher for a fire in an energized computer panel. This shows:','["using water", "random choice", "choosing the appropriate extinguisher for each fire class", "avoiding extinguishers"]'::jsonb,2,'CO2 is non-conductive.','original'),
('127.749.d.3.B',4,'Which extinguisher is the correct choice for a flammable liquid fire?','["a Class A water can", "a garden hose", "a broom", "a Class B-rated extinguisher"]'::jsonb,3,'Class B covers flammable liquids.','original'),
('127.749.d.3.C',3,'A technician notes an extinguisher''s agent, range, discharge time and pressure gauge. These are its:','["characteristics and operations", "colors only", "brand only", "shape only"]'::jsonb,0,'Characteristics inform use.','original'),
('127.749.d.3.C',4,'Before using an extinguisher, a firefighter checks the gauge to be sure the:','["label is new", "pressure is in the operable range", "handle is red", "pin is rusty"]'::jsonb,1,'A full charge is needed.','original'),
('127.749.d.3.D',3,'A trainee pulls the pin, aims at the base of the fire, squeezes the handle and sweeps side to side. This is the:','["ladder carry", "fire triangle", "PASS method for operating an extinguisher", "hose lay"]'::jsonb,2,'Pull, Aim, Squeeze, Sweep.','original'),
('127.749.d.3.D',4,'In the PASS method, the ''Aim'' step means to point the nozzle at:','["the ceiling", "the wall", "the top of the flames", "the base of the fire"]'::jsonb,3,'Aim low at the base.','original'),
('127.749.d.4.A',3,'Ground ladders may be made of aluminum, fiberglass or wood. These are the:','["materials used in ladder construction", "brands of ladders", "sizes of hoses", "colors of ladders"]'::jsonb,0,'Each material has pros and cons.','original'),
('127.749.d.4.A',4,'Why are fiberglass ladders used near power lines?','["It is cheaper", "Fiberglass does not conduct electricity like metal does", "It is heavier", "It is invisible"]'::jsonb,1,'Non-conductive.','original'),
('127.749.d.4.B',3,'Before a ladder is placed back on the truck, a firefighter checks rungs, rails, pulleys and heat-sensor labels. This is:','["painting", "ignoring damage", "inspection and maintenance of ground ladders", "tossing it"]'::jsonb,2,'Inspection prevents failures.','original'),
('127.749.d.4.B',4,'A ladder with a cracked rung should be:','["used for light work", "used with caution", "painted over", "taken out of service until repaired"]'::jsonb,3,'Damaged ladders are unsafe.','original'),
('127.749.d.4.C',3,'The weight a ladder can safely carry is called its:','["load capacity", "age", "rung color", "length"]'::jsonb,0,'Load capacity is a safety rating.','original'),
('127.749.d.4.C',4,'Exceeding a ground ladder''s load capacity can cause:','["a lighter ladder", "ladder failure and injury", "a quieter climb", "a faster climb"]'::jsonb,1,'Overloading is dangerous.','original'),
('127.749.d.4.D',3,'To reach a third-floor window, a crew picks a ladder long enough to extend a few rungs above the sill. This is:','["random choice", "ignoring size", "selecting a ladder for a given task", "guessing"]'::jsonb,2,'Match the ladder to the job.','original'),
('127.749.d.4.D',4,'When selecting a ladder to reach a roof edge, firefighters should consider:','["its color", "its brand only", "its age only", "its length, load rating and the angle needed"]'::jsonb,3,'Select for length and safety.','original'),
('127.749.d.4.E',3,'Two firefighters carry a ladder to the wall, lift it and place its base at the correct distance. This is:','["raising and positioning a ground ladder", "avoiding practice", "ignoring safety", "dropping a ladder"]'::jsonb,0,'Safe raising needs teamwork.','original'),
('127.749.d.4.E',4,'A common rule for ladder angle is that the base should be placed:','["upside down", "about one-quarter of the working height from the wall", "flush against the wall", "far from the wall"]'::jsonb,1,'A 4-to-1 rule gives a safe angle.','original'),
('127.749.d.4.F',3,'After placing a ladder, a firefighter foots the ladder or ties it off so it won''t slip. This is:','["moving a ladder", "dropping a ladder", "securing a ladder", "ignoring a ladder"]'::jsonb,2,'A secured ladder is stable.','original'),
('127.749.d.4.F',4,'The purpose of securing a ladder before climbing is to:','["make it louder", "make it shorter", "make it heavier", "prevent slipping or shifting"]'::jsonb,3,'Stability prevents falls.','original'),
('127.749.d.4.G',3,'A firefighter carries a pike pole up a ladder using one hand and keeping three points of contact. This is:','["proper climbing technique while transporting tools", "unsafe climbing", "racing", "skipping steps"]'::jsonb,0,'Tools must be carried safely.','original'),
('127.749.d.4.G',4,'While climbing a ladder with a tool, a firefighter should:','["jump off", "keep a hand and firm footing on the ladder at all times", "carry with both hands", "slide down"]'::jsonb,1,'Stay in contact with the ladder.','original'),
('127.749.d.4.H',3,'On a pitched roof, a crew uses a ladder with hooks that anchors over the ridge to give footing. This is:','["running a hose", "avoiding roofs", "deploying a roof ladder", "dropping a ladder"]'::jsonb,2,'Roof ladders provide stable footing.','original'),
('127.749.d.4.H',4,'A roof ladder''s hooks are placed over the:','["gutter", "chimney cap", "window", "ridge of the roof"]'::jsonb,3,'Hooks anchor at the ridge.','original'),
('127.749.d.5.A',3,'Fire hose is built with a jacket and liner, with metal or plastic couplings at each end. This describes:','["the use and construction of fire hoses and couplings", "helmets", "extinguishers", "ladders"]'::jsonb,0,'Hose construction determines use.','original'),
('127.749.d.5.A',4,'A coupling on a fire hose allows the hose to:','["heat up", "connect to other hose, nozzles or hydrants", "change color", "stretch forever"]'::jsonb,1,'Couplings join equipment.','original'),
('127.749.d.5.B',3,'An engine carries larger-diameter supply hose for long water lines and smaller attack hose for fire attack. This explains:','["empty hose", "random hose", "the application of each size and type of hose", "decorative hose"]'::jsonb,2,'Hose size matches the task.','original'),
('127.749.d.5.B',4,'A supply line that carries water from a hydrant to the pumper is usually:','["tiny garden hose", "electric cable", "booster only", "large-diameter hose"]'::jsonb,3,'Supply lines need big flow.','original'),
('127.749.d.5.C',3,'A firefighter aligns two Storz couplings and twists them to lock. This shows:','["a method of connecting fire hose couplings", "burning hose", "drying hose", "cutting hose"]'::jsonb,0,'Couplings connect in set ways.','original'),
('127.749.d.5.C',4,'Before connecting hose couplings, firefighters check that the gaskets are:','["dirty", "present and clean", "torn", "missing"]'::jsonb,1,'Gaskets prevent leaks.','original'),
('127.749.d.5.D',3,'One firefighter and then two firefighters practice joining, breaking apart and rolling a section of hose. This is:','["tangling hose", "tossing hose", "one- and two-person methods for connecting, dismantling and rolling hose", "ignoring hose"]'::jsonb,2,'Hose handling is taught with partners.','original'),
('127.749.d.5.D',4,'When rolling hose after a fire, firefighters should first:','["stomp it", "roll it wet and dirty", "leave it", "drain and clean it so it can be rolled properly"]'::jsonb,3,'Preparation protects hose.','original'),
('127.749.d.5.E',3,'A crew pulls an empty hose line to the door and then charges it with water as they advance. This is:','["advancing dry and charged attack lines", "ignoring fire", "running away", "retreating"]'::jsonb,0,'Advancing lines is a core skill.','original'),
('127.749.d.5.E',4,'A charged hose line compared with an empty one is:','["invisible", "heavier and more rigid", "lighter and flexible", "weightless"]'::jsonb,1,'Water adds weight.','original'),
('127.749.d.5.F',3,'Hose loads can be finished in several ways such as a horseshoe or a flat load. These are:','["fire classes", "ladder types", "hose load finishes", "helmet styles"]'::jsonb,2,'Finishes help pull and advance hose.','original'),
('127.749.d.5.F',4,'A hose load finish is designed so that hose will:','["tie in knots", "tangle", "stay in the bed", "deploy smoothly and without tangles"]'::jsonb,3,'Good loads deploy cleanly.','original'),
('127.749.d.5.G',3,'A hose bursts at a fire, so a crew shuts off the water, replaces the section and restarts flow. This is:','["extending and replacing damaged hose", "running away", "ignoring the problem", "dropping the line"]'::jsonb,0,'Damaged sections are replaced.','original'),
('127.749.d.5.G',4,'Before replacing a damaged hose section, firefighters should:','["keep flow on", "shut down the water flow to that line", "cut the line", "increase pressure"]'::jsonb,1,'Safety before repair.','original'),
('127.749.d.5.H',3,'After a fire, crews wash hose with mild soap and hang it to dry to prevent mildew. These are:','["methods of cutting", "methods of burning", "methods of washing and drying fire hose", "methods of dropping"]'::jsonb,2,'Hose care extends its life.','original'),
('127.749.d.5.H',4,'Why must a fire hose be dried before storage?','["It is a tradition", "Dry hose is heavier", "Water helps it last", "Moisture can cause mildew and weaken the jacket"]'::jsonb,3,'Dry storage prevents damage.','original'),
('127.749.d.6.A',3,'A straight stream, a fog stream and a solid stream behave differently on a fire. These are:','["characteristics of fire streams", "types of ladders", "brands of nozzle", "colors of hose"]'::jsonb,0,'Streams differ by pattern and reach.','original'),
('127.749.d.6.A',4,'A straight stream is best used when a firefighter needs:','["less water", "reach and penetration", "no pressure", "a wide curtain"]'::jsonb,1,'Straight streams reach far.','original'),
('127.749.d.6.B',3,'A nozzle label lists its flow in gallons per minute and the pressure it needs. This helps identify:','["the weight only", "the brand only", "the type, design, operation and required pressure of a nozzle", "the color"]'::jsonb,2,'Specs guide use.','original'),
('127.749.d.6.B',4,'A smooth-bore nozzle typically provides:','["no water", "a mist", "a fog only", "a solid stream with good reach"]'::jsonb,3,'Smooth bore gives a solid stream.','original'),
('127.749.d.6.C',3,'A firefighter uses a gated wye, a reducer and a nozzle to split one line into two. This is:','["proper use of nozzles, hose appliances, valves and adapters", "guessing", "avoiding appliances", "misusing tools"]'::jsonb,0,'Appliances manage water flow.','original'),
('127.749.d.6.C',4,'A wye appliance lets a crew:','["combine two lines to one", "divide one hose line into two", "stop all flow", "burn hose"]'::jsonb,1,'Wyes split lines.','original'),
('127.749.d.6.D',3,'Pistol grips, bails, tips and shutoff valves are all components of a:','["helmet", "ladder", "fire nozzle", "hydrant"]'::jsonb,2,'Nozzles have several parts.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_96_v1'
from (values
('127.749.d.6.D',4,'A nozzle''s shutoff allows the firefighter to:','["raise the pump", "lock the door", "change the color", "start and stop the water flow"]'::jsonb,3,'Shutoffs control flow.','original'),
('127.749.d.6.E',3,'Terms such as friction loss, flow rate and pressure are:','["terms related to fire service hydraulics", "sports terms", "food terms", "art terms"]'::jsonb,0,'Hydraulics explains water movement.','original'),
('127.749.d.6.E',4,'Friction loss in a hose line refers to:','["the gain of pressure", "the drop in pressure caused by water moving through the hose", "the height of the ladder", "the speed of the truck"]'::jsonb,1,'Friction reduces pressure.','original'),
('127.749.d.7.A',3,'A hydrant is opened fully for flow and the water is shut off slowly, never abruptly. This describes:','["random operation", "a hydrant failure", "the proper operation of fire hydrants", "a hose test"]'::jsonb,2,'Slow operation prevents water hammer.','original'),
('127.749.d.7.A',4,'Opening a hydrant slowly and fully helps avoid:','["loud noise only", "low flow", "cold water", "damage from surges in the water system"]'::jsonb,3,'Gradual operation protects equipment.','original'),
('127.749.d.7.B',3,'A hydrant painted with a certain cap color tells firefighters its flow capacity. This is the:','["NFPA hydrant color code", "paint code", "uniform code", "traffic code"]'::jsonb,0,'Colors indicate flow rates.','original'),
('127.749.d.7.B',4,'Under the NFPA hydrant color code, a hydrant with a red cap indicates:','["out of service only", "the lowest flow capacity", "no water", "the highest flow"]'::jsonb,1,'Red is under 500 gpm.','original'),
('127.749.d.7.C',3,'A firefighter connects a large hose from the hydrant outlet to the pumper intake. This is making a:','["tank refill", "roof ladder lift", "hydrant-to-pumper connection", "nozzle test"]'::jsonb,2,'The connection supplies water.','original'),
('127.749.d.7.C',4,'Before connecting a hydrant, firefighters should:','["close the cap", "paint it", "ignore it", "flush the hydrant to clear debris"]'::jsonb,3,'Flushing prevents debris in the pump.','original'),
('127.749.d.7.D',3,'A poorly connected supply line may leak, whip or burst when charged. These are:','["hazards of an improper hydrant-to-pumper connection", "routine events", "benefits", "design features"]'::jsonb,0,'Improper connections are dangerous.','original'),
('127.749.d.7.D',4,'A loose coupling on a charged hydrant line can result in:','["cooler water", "injury to crew and loss of water supply", "better pressure", "extra water"]'::jsonb,1,'Loose connections are hazardous.','original'),
('127.749.d.7.E',3,'Where there are no hydrants, firefighters use tankers, portable tanks and pumps to supply water. This describes:','["no supply", "random supply", "apparatus and appliances to provide water in rural areas", "urban supply"]'::jsonb,2,'Rural water supply uses shuttles and tanks.','original'),
('127.749.d.7.E',4,'In a rural area without hydrants, firefighters might create a water supply using:','["an empty barrel", "only a garden hose", "a sponge", "a tanker shuttle with portable drop tanks"]'::jsonb,3,'Tankers and drop tanks supply water.','original'),
('127.749.d.8.A',3,'After a house fire, crews remove burned materials and wet debris to prevent rekindling. This is:','["handling debris from fires", "starting a fire", "spreading debris", "ignoring cleanup"]'::jsonb,0,'Overhaul removes hidden fire sources.','original'),
('127.749.d.8.A',4,'Firefighters handle debris from a chemical fire differently because it may:','["be lighter", "contain hazardous residues", "be harmless", "be scented"]'::jsonb,1,'Chemical debris needs special handling.','original'),
('127.749.d.8.B',3,'An officer notes burn patterns, witnesses'' statements and the first area of ignition to help investigators. These are:','["ignoring evidence", "guessing", "duties for gathering information about the cause of a fire", "closing a case"]'::jsonb,2,'Early notes help cause determination.','original'),
('127.749.d.8.B',4,'Why must firefighters preserve the area of origin after a fire?','["It is a rule for decoration", "It saves time", "It improves cleanup", "It may hold evidence needed to determine the cause"]'::jsonb,3,'Preserve evidence.','original'),
('127.749.d.8.C',3,'After the fire is out, firefighters secure the building, board openings and protect the property. This is:','["restoration of the premises after a fire", "starting another fire", "abandoning the building", "stealing property"]'::jsonb,0,'Restoration secures and protects.','original'),
('127.749.d.8.C',4,'Securing a damaged building after a fire helps prevent:','["traffic", "theft, entry by others and further damage", "pets", "loud noise only"]'::jsonb,1,'Securing protects property.','original'),
('127.749.d.8.D',3,'A firefighter stays at the fire scene watching for rekindling and guarding the property. These are duties of:','["ignoring the scene", "sleeping", "fire and security surveillance during and after a fire", "leaving early"]'::jsonb,2,'Surveillance prevents rekindles.','original'),
('127.749.d.8.D',4,'A fire watch after a large fire is kept to:','["increase noise", "deliver supplies", "avoid training", "catch hidden hot spots that might reignite"]'::jsonb,3,'Rekindles can occur.','original'),
('127.750.d.1.A',3,'In a police academy lesson, a cadet defines ''reasonable force'' and cites the law that lets an officer use force when making an arrest. This is learning:','["use-of-force terminology and legal authority", "parking rules", "radio brands", "uniform styles"]'::jsonb,0,'Officers need to know terms and legal authority.','original'),
('127.750.d.1.A',4,'Legal authority for an officer to use force generally comes from:','["a coin flip", "state law and constitutional limits", "personal choice", "a supervisor''s mood"]'::jsonb,1,'Law defines when force is allowed.','original'),
('127.750.d.1.B',3,'An officer weighs the suspect''s actions, the threat level and the available options before deciding whether to use force during an arrest. These are:','["irrelevant details", "guesses", "deciding factors for use of force", "jokes"]'::jsonb,2,'Force depends on the situation.','original'),
('127.750.d.1.B',4,'Which factor most directly affects the amount of force justified in an arrest?','["the car''s color", "the officer''s mood", "the weather", "how much the suspect resists or threatens the officer or others"]'::jsonb,3,'Force must be proportional to resistance and threat.','original'),
('127.750.d.1.C',3,'A lone officer approaches a dark building where a burglary alarm sounded. Such situations are considered:','["high-risk circumstances for officers", "safe routine tasks", "holiday events", "paperwork"]'::jsonb,0,'Unknown threats raise risk.','original'),
('127.750.d.1.C',4,'Which situation is generally a high risk for officers?','["a routine desk shift", "a felony vehicle stop", "a library tour", "a school assembly"]'::jsonb,1,'Felony stops can involve armed suspects.','original'),
('127.750.d.1.D',3,'A trainer shows that talking, a control hold, a baton and a firearm are different options on a force scale. This raises awareness of:','["only deadly force", "one tool for all situations", "force options and alternatives", "no options"]'::jsonb,2,'Officers have multiple options.','original'),
('127.750.d.1.D',4,'Considering alternatives to force first is useful because it:','["removes training", "ends law enforcement", "wastes time", "can resolve situations with less risk of injury"]'::jsonb,3,'De-escalation reduces harm.','original'),
('127.750.d.1.E',3,'Peace officers may use verbal commands, soft restraints, tools such as batons or conducted energy weapons, or firearms as a last resort. These are:','["force options available to peace officers", "fashion choices", "hobbies", "office tasks"]'::jsonb,0,'Several options exist along a continuum.','original'),
('127.750.d.1.E',4,'The use of lethal force by an officer is generally allowed only when:','["the officer is annoyed", "there is a serious threat of death or serious injury", "a person runs from a minor ticket", "a suspect is rude"]'::jsonb,1,'Deadly force is limited to grave threats.','original'),
('127.750.d.1.F',3,'A patrol officer scans for weapons, watches hands and keeps a safe distance during a contact. This shows:','["ignoring surroundings", "looking away", "recognizing and controlling elements in every encounter", "casual chatting only"]'::jsonb,2,'Control of the encounter protects safety.','original'),
('127.750.d.1.F',4,'Maintaining a position of advantage and awareness during a stop helps an officer to:','["ignore the suspect", "avoid reports", "hide evidence", "control the encounter and respond to changes"]'::jsonb,3,'Positioning improves safety.','original'),
('127.750.d.2.A',3,'A cadet learns what ''probable cause'', ''warrant'' and ''arraignment'' mean before studying case law. This is relating:','["technical concepts and vocabulary associated with law enforcement", "sports terms", "recipes", "music"]'::jsonb,0,'Terminology supports learning.','original'),
('127.750.d.2.A',4,'Which term describes a judge''s written order authorizing police to search a place?','["a report card", "a search warrant", "a traffic cone", "a badge"]'::jsonb,1,'Warrants authorize searches.','original'),
('127.750.d.2.B',3,'Eye contact, crossed arms and nervous gestures give an officer clues about a person''s feelings during an interview. This is interpreting:','["written grammar", "only words", "facial expressions, gestures and body posture", "badge numbers"]'::jsonb,2,'Non-verbal cues convey meaning.','original'),
('127.750.d.2.B',4,'A person who avoids eye contact and fidgets during questioning is showing:','["a legal fact", "proof of guilt", "proof of innocence", "nonverbal cues that may or may not indicate stress"]'::jsonb,3,'Cues require context and are not proof.','original'),
('127.750.d.2.C',3,'A witness whose voice rises and quickens when describing a robbery is conveying emotion through:','["pitch, tone and word choice", "only spelling", "only grammar", "only badges"]'::jsonb,0,'Vocal delivery carries meaning.','original'),
('127.750.d.2.C',4,'Which is an example of voice quality an officer would interpret?','["a printed report", "a trembling, high-pitched voice", "a map", "a typed message"]'::jsonb,1,'Voice cues show emotion.','original'),
('127.750.d.2.D',3,'An officer greets residents in their own language and respects local customs when taking a report. This shows:','["avoiding the public", "ignoring differences", "recognizing diversity in culture", "stereotyping"]'::jsonb,2,'Cultural awareness builds trust.','original'),
('127.750.d.2.D',4,'Recognizing cultural diversity helps officers to:','["ignore concerns", "avoid training", "treat all situations the same without thought", "communicate respectfully and avoid misunderstandings"]'::jsonb,3,'Understanding supports effective communication.','original'),
('127.750.d.2.E',3,'During a briefing, a cadet makes eye contact, nods and later summarizes what the sergeant said. This is:','["employing active listening skills", "sleeping", "interrupting", "ignoring the briefing"]'::jsonb,0,'Summarizing shows understanding.','original'),
('127.750.d.2.E',4,'Which action is an example of active listening?','["Checking a phone", "Paraphrasing what was said to confirm understanding", "Talking over others", "Leaving"]'::jsonb,1,'Paraphrasing confirms understanding.','original'),
('127.750.d.2.F',3,'At a shift meeting, an officer shares an idea about neighborhood patrols and listens to others'' ideas. This is:','["ignoring ideas", "avoiding meetings", "contributing to group discussions and meetings", "dominating"]'::jsonb,2,'Participation improves teamwork.','original'),
('127.750.d.2.F',4,'A constructive way to contribute in a meeting is to:','["stay silent always", "interrupt often", "criticize without reason", "offer relevant ideas and respect others'' views"]'::jsonb,3,'Good participation is respectful.','original'),
('127.750.d.3.A',3,'A cadet fills in the date, location, vehicles, drivers and diagram for a two-car collision. This is producing a:','["crash report", "traffic ticket", "arrest warrant", "parking permit"]'::jsonb,0,'Crash reports record facts.','original'),
('127.750.d.3.A',4,'An accurate crash report should include:','["only gossip", "time, place, vehicles, people involved and a diagram", "only opinions", "only the weather"]'::jsonb,1,'Reports need complete factual detail.','original'),
('127.750.d.3.B',3,'After a crash, an officer cites the Texas Transportation Code on failing to yield right of way. This is applying:','["guessing", "avoiding the law", "laws associated with accident investigation", "skipping the report"]'::jsonb,2,'Investigators apply traffic law.','original'),
('127.750.d.3.B',4,'Under Texas law, drivers involved in a crash that causes injury must:','["leave quickly", "hide", "ignore the injured", "stop and give information and aid"]'::jsonb,3,'Duty upon involvement.','original'),
('127.750.d.3.C',3,'Officers learn to park to protect the scene, turn on lights and call for help before starting an investigation. This researches:','["procedures for responding to an accident scene and maintaining control", "leaving early", "avoiding the scene", "blocking help"]'::jsonb,0,'Scene control protects people.','original'),
('127.750.d.3.C',4,'The first priority at an accident scene is usually to:','["move all cars", "ensure safety and get help to anyone injured", "write tickets", "measure skid marks"]'::jsonb,1,'Life safety first.','original'),
('127.750.d.3.D',3,'An officer uses cones, flares and hand signals to guide cars around a wreck. This is:','["ignoring drivers", "blocking the road at random", "maintaining traffic control at an accident scene", "creating traffic jams"]'::jsonb,2,'Traffic control protects responders.','original'),
('127.750.d.3.D',4,'Which action helps maintain traffic control at a crash?','["Standing in the lane", "Removing all signs", "Turning off lights", "Placing warning devices well before the scene"]'::jsonb,3,'Advance warning prevents secondary crashes.','original'),
('127.750.d.4.A',3,'The Constitution sets limits on police power, such as protecting people from unreasonable searches. This explains the Constitution''s role in:','["developing and implementing law enforcement policy", "only school rules", "no policy", "only taxes"]'::jsonb,0,'Policies reflect constitutional limits.','original'),
('127.750.d.4.A',4,'Which part of the U.S. Constitution most directly protects people from unreasonable searches?','["the Third Amendment", "the Fourth Amendment", "the Twelfth Amendment", "the Second Amendment"]'::jsonb,1,'Fourth Amendment covers searches and seizures.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_96_v1'
from (values
('127.750.d.4.B',3,'A cadet considers whether an officer should keep a gift left by a grateful resident. This is evaluating:','["traffic rules", "hobbies", "individual ethical behavior standards", "fashion"]'::jsonb,2,'Ethics guide conduct.','original'),
('127.750.d.4.B',4,'A standard of ethical behavior for officers includes:','["hiding errors", "favoritism", "bending rules", "honesty, fairness and respect for rights"]'::jsonb,3,'Ethical behavior is essential.','original'),
('127.750.d.4.C',3,'An agency''s code of conduct and the law both forbid planting evidence because it violates citizens'' rights. This is:','["legal and ethical standards protecting constitutional rights", "a game", "optional advice", "a rumor"]'::jsonb,0,'Law and ethics protect rights.','original'),
('127.750.d.4.C',4,'Why are legal and ethical standards important in policing?','["They end arrests", "They protect citizens'' rights and public trust", "They add paperwork", "They limit patrols"]'::jsonb,1,'Rights and trust are the goal.','original'),
('127.750.d.4.D',3,'An officer attends neighborhood meetings, responds politely and explains actions to residents. These are strategies to:','["limit transparency", "reduce trust", "enhance public trust", "avoid the public"]'::jsonb,2,'Open communication builds trust.','original'),
('127.750.d.4.D',4,'Which action best enhances public trust in the police?','["Avoiding questions", "Using force often", "Ignoring complaints", "Being transparent, respectful and fair"]'::jsonb,3,'Fair treatment earns trust.','original'),
('127.750.d.4.E',3,'A law enforcement agency''s mission statement says it protects lives, property and rights in a free society. This is its:','["mission in protecting a democratic society", "menu", "slogan for sports", "fashion goal"]'::jsonb,0,'Police protect democratic values.','original'),
('127.750.d.4.E',4,'The mission of law enforcement in a democracy includes:','["ignoring rights", "enforcing the law while protecting individual rights", "avoiding the public", "using unlimited power"]'::jsonb,1,'Rights and order go together.','original'),
('127.750.d.5.A',3,'A resident is protected from being searched without a warrant by the U.S. Constitution, the Texas Constitution and city rules. This shows:','["one level only", "no protection", "protection by constitutional laws at local, state and federal levels", "rumors"]'::jsonb,2,'Multiple layers of law protect citizens.','original'),
('127.750.d.5.A',4,'Which statement is true about constitutional protection of citizens?','["Only federal law applies", "No laws apply to police", "Only city law applies", "Federal, state and local laws all place limits on police actions"]'::jsonb,3,'Layered protections.','original'),
('127.750.d.5.B',3,'In Mapp v. Ohio, the Supreme Court held that evidence obtained through an illegal search cannot be used in state courts. This is the:','["exclusionary rule applied to the states", "Miranda rule", "double jeopardy", "speedy-trial rule"]'::jsonb,0,'Mapp extended the rule.','original'),
('127.750.d.5.B',4,'Terry v. Ohio allows an officer to briefly stop and pat down a person if the officer has:','["a hunch only", "reasonable suspicion that the person is armed and dangerous", "a dislike", "no reason"]'::jsonb,1,'Terry permits limited stop-and-frisk.','original'),
('127.750.d.5.C',3,'A city ordinance, a state statute and a federal law may all address the same behavior. This shows the:','["conflict of rules only", "absence of law", "similarities, differences and interactions of local, state and federal law", "random rules"]'::jsonb,2,'Laws overlap and interact.','original'),
('127.750.d.5.C',4,'If a local law conflicts with the U.S. Constitution, the:','["state law controls", "local law controls", "the police chief decides", "Constitution controls"]'::jsonb,3,'The Constitution is supreme law.','original'),
('127.750.d.5.D',3,'A case begins with an arrest, moves to a hearing, then a trial and perhaps an appeal. This illustrates:','["the progression of a case through local, state and federal courts", "a traffic stop", "a random event", "a patrol shift"]'::jsonb,0,'Cases proceed through stages.','original'),
('127.750.d.5.D',4,'A losing party who thinks a legal error occurred can:','["start over without notice", "appeal to a higher court", "call the arresting officer", "ignore the ruling"]'::jsonb,1,'Appeals review legal error.','original'),
('127.750.d.5.E',3,'A person sues a company for damages, while the state charges a person with burglary. These show:','["weather patterns", "no difference", "differences between civil and criminal court systems", "sports leagues"]'::jsonb,2,'Civil seeks remedies; criminal seeks punishment.','original'),
('127.750.d.5.E',4,'A key characteristic of criminal cases is that the government must prove guilt:','["by a hunch", "by a simple majority of opinions", "by a rumor", "beyond a reasonable doubt"]'::jsonb,3,'Higher standard in criminal cases.','original'),
('127.750.d.6.A',3,'An officer reads a suspect the Miranda warning before custodial questioning begins. This applies the:','["constitutional rights against self-incrimination and to counsel", "school rule", "tax law", "traffic law"]'::jsonb,0,'Miranda protects Fifth and Sixth Amendment rights.','original'),
('127.750.d.6.A',4,'Miranda warnings must be given before questioning when a person is:','["asking for directions", "in custody and subject to interrogation", "paying a fee", "walking in public"]'::jsonb,1,'Custody plus interrogation triggers Miranda.','original'),
('127.750.d.6.B',3,'When a juvenile is a suspect, Texas law adds steps such as taking the child before a magistrate for warnings. This explains:','["adult rules only", "no requirements", "additional requirements beyond Miranda for juvenile suspects", "fewer requirements"]'::jsonb,2,'Juveniles have extra protections.','original'),
('127.750.d.6.B',4,'Compared with adults, juvenile suspects in Texas receive:','["fewer rights", "no counsel", "no warnings", "extra procedural protections before a statement can be used"]'::jsonb,3,'Juvenile law adds safeguards.','original'),
('127.750.d.6.C',3,'A trainee practices an informal talk with a witness who is free to leave and a formal questioning of a suspect in custody. This demonstrates:','["non-custodial and custodial interviews and interrogation", "no technique", "only one kind of talk", "avoiding talks"]'::jsonb,0,'Custody changes the rules.','original'),
('127.750.d.6.C',4,'The main difference between a non-custodial and custodial interview is that in a custodial interview:','["no notes are taken", "the person is not free to leave", "no one is present", "no law applies"]'::jsonb,1,'Custody triggers rights.','original'),
('127.750.d.7.A',3,'The Texas Penal Code sorts crimes into classes such as felonies and misdemeanors with different punishments. This defines:','["only traffic", "no categories", "crime categories and their punishments", "only weather"]'::jsonb,2,'Categories set penalties.','original'),
('127.750.d.7.A',4,'In Texas, a Class C misdemeanor is punishable by:','["five years in jail", "the death penalty", "life in prison", "a fine only"]'::jsonb,3,'Class C is fine only.','original'),
('127.750.d.7.B',3,'To prove driving while intoxicated, the state must show the person was driving and was intoxicated. These are:','["elements of a criminal act under Texas law", "opinions", "rumors", "unrelated facts"]'::jsonb,0,'Elements are the parts of a crime.','original'),
('127.750.d.7.B',4,'Which is an element commonly required for a driving-while-intoxicated charge?','["paying a toll", "operating a motor vehicle in a public place while intoxicated", "wearing a seat belt", "owning a car"]'::jsonb,1,'Operating while intoxicated is an element.','original'),
('127.750.d.7.C',3,'Murder is wrong in itself, while speeding is wrong only because a law prohibits it. These examples show:','["jury and judge", "felony and bail", "mala in se and mala prohibita", "civil and criminal"]'::jsonb,2,'Mala in se = inherently wrong; mala prohibita = prohibited by law.','original'),
('127.750.d.7.C',4,'Which is an example of mala prohibita?','["assault", "robbery", "murder", "driving without a required license"]'::jsonb,3,'It is wrong because law prohibits it.','original'),
('127.750.d.7.D',3,'A person charged with assault claims they acted to protect themselves from an attack. This is a type of:','["criminal defense (self-defense)", "confession", "bail", "arrest"]'::jsonb,0,'Self-defense is a justification defense.','original'),
('127.750.d.7.D',4,'A defendant who proves they were not at the scene because they were elsewhere is using:','["a self-defense claim", "an alibi defense", "an insanity defense", "a plea bargain"]'::jsonb,1,'Alibi means elsewhere at the time.','original'),
('127.750.d.8.A',3,'A bill of rights for crime victims gives them the right to be informed and treated fairly in the justice process. This relates to:','["school rules", "rights of suspects only", "the rights of victims of crimes and witnesses", "traffic rules"]'::jsonb,2,'Victims have legal rights.','original'),
('127.750.d.8.A',4,'Under Texas law, a crime victim has the right to:','["skip court always", "control the verdict", "hold the trial", "be treated with fairness and be informed about the case"]'::jsonb,3,'Fairness and information are standard rights.','original'),
('127.750.d.8.B.i',3,'A burglary victim feels afraid in her home for months after the crime. This is an example of the:','["psychological impact of crime on the victim", "ignorable effect", "economic gain", "trivial effect"]'::jsonb,0,'Crime can cause lasting fear and stress.','original'),
('127.750.d.8.B.i',4,'Symptoms such as anxiety, sleeplessness and fear after a violent crime are examples of the:','["social perks", "psychological effects on victims", "economic benefits", "legal rewards"]'::jsonb,1,'Psychological harm is common.','original'),
('127.750.d.8.B.ii',3,'A crime victim loses work time, pays medical bills and replaces stolen items. These are examples of the:','["fashion", "no effect", "economic impact of crime on the victim", "gain"]'::jsonb,2,'Crime brings financial costs.','original'),
('127.750.d.8.B.ii',4,'A victim who withdraws from friends and avoids public places after being attacked is showing a:','["economic reward", "civil benefit", "legal benefit", "social impact of crime on the victim"]'::jsonb,3,'Crime can isolate victims.','original'),
('127.750.d.8.C.i',3,'An officer gives a victim a card explaining services and contact numbers for the district attorney''s victim services. This is a:','["statutory responsibility to inform victims of their rights and services", "trivial matter", "optional gift", "private favor"]'::jsonb,0,'Law requires officers to provide information.','original'),
('127.750.d.8.C.i',4,'The agency that typically assists crime victims with the court process is the:','["school board", "victim assistance office of the prosecutor", "parks department", "public library"]'::jsonb,1,'Prosecutor offices provide victim services.','original'),
('127.750.d.8.C.ii',3,'An officer summarizes how a victim can apply for crime victims'' compensation to cover medical costs. This is a:','["unrelated duty", "private choice", "statutory responsibility relating to victims'' rights", "gift"]'::jsonb,2,'Officers must inform victims of compensation.','original'),
('127.750.d.8.C.ii',4,'Crime victims'' compensation helps victims by:','["ending the case", "punishing the offender", "paying lawyers'' fees", "paying certain costs such as medical bills or lost wages"]'::jsonb,3,'Compensation reimburses certain costs.','original'),
('127.750.d.8.C.iii',3,'An officer explains that a victim may give a statement about how a crime affected them before sentencing. This is a:','["victim impact statement", "search warrant", "traffic ticket", "arrest report"]'::jsonb,0,'Victim impact statements describe harm.','original'),
('127.750.d.8.C.iii',4,'A victim impact statement allows the court to learn about:','["the officer''s pay", "the effects of the crime on the victim", "the jury''s names", "the weather"]'::jsonb,1,'The court considers the harm done.','original'),
('127.750.d.9.A',3,'A patrol officer finds a 15-year-old skipping school and follows the steps for a status offense, which is conduct that is illegal only because of the person''s age. This is:','["adult sentencing", "a felony arrest", "juvenile law relating to status offenses", "a civil suit"]'::jsonb,2,'Status offenses apply to minors.','original'),
('127.750.d.9.A',4,'Which is an example of a status offense?','["robbery", "assault", "burglary", "truancy"]'::jsonb,3,'Truancy is illegal only for minors.','original'),
('127.750.d.9.B',3,'An officer meets with a juvenile and the parents together to explain the problem and options. This is:','["holding a conference with juveniles and parents or guardians", "a trial", "avoiding parents", "an arrest"]'::jsonb,0,'Conferences involve the family.','original'),
('127.750.d.9.B',4,'A purpose of a conference with a juvenile and parents is to:','["skip procedure", "discuss the behavior and plan for correction", "ignore the child", "punish the parents"]'::jsonb,1,'Conferences can resolve minor issues.','original'),
('127.750.d.10.A.i',3,'An officer learns that family violence often follows a cycle of tension, an incident and reconciliation. This is understanding the:','["rare event", "simple argument only", "dynamics of family violence", "civil case only"]'::jsonb,2,'Cycles help explain repeated abuse.','original'),
('127.750.d.10.A.i',4,'A victim of family violence may stay with an abuser because of:','["never being harmed", "no reason at all", "enjoying the violence", "fear, dependence or hope that the abuse will stop"]'::jsonb,3,'Victims face complex pressures.','original'),
('127.750.d.10.A.ii',3,'An officer must know Texas law''s definitions of ''family violence'' and ''child abuse'' to decide whether a crime occurred. These are:','["legal issues of family violence and child abuse", "parking rules", "school rules", "recipes"]'::jsonb,0,'Definitions guide actions.','original'),
('127.750.d.10.A.ii',4,'Under Texas law, family violence includes acts that cause or threaten:','["a missed meal", "physical harm or fear of imminent physical harm within a family or household", "a lost phone", "a verbal joke"]'::jsonb,1,'The statute covers harm or threats.','original'),
('127.750.d.10.A.iii',3,'A teacher who suspects a child is being abused must make a report to authorities. This is the legal duty of:','["hiding it", "optional reporting", "mandatory reporting of suspected child abuse", "waiting a year"]'::jsonb,2,'Texas law requires reporting.','original'),
('127.750.d.10.A.iii',4,'In Texas, a person who suspects child abuse or neglect is required to:','["wait for proof", "tell only a friend", "avoid involvement", "report it to authorities such as DFPS or law enforcement"]'::jsonb,3,'Reporting is required by law.','original'),
('127.750.d.10.B.i',3,'Responding to a family violence call, the officer separates the people, checks for injuries and interviews each person apart. This is a recommended step when:','["handling family violence calls", "leaving", "interviewing together only", "ignoring the call"]'::jsonb,0,'Separate interviews protect victims.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
