select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_96_v1'
from (values
('127.750.d.10.B.i',4,'An officer''s first step on arriving at a family violence call is to:','["write a report", "ensure safety and check for injuries", "argue with the parties", "leave the home"]'::jsonb,1,'Safety and aid come first.','original'),
('127.750.d.10.B.ii',3,'An officer explains to a victim that a court can issue a protective order to keep the abuser away. This is part of handling calls involving:','["school visits", "traffic stops", "protective orders in family violence cases", "parking tickets"]'::jsonb,2,'Protective orders can restrict contact.','original'),
('127.750.d.10.B.ii',4,'A protective order in a family violence case generally orders the abuser to:','["pay a fine only", "write a letter", "move in", "stay away from the protected person"]'::jsonb,3,'Protective orders prohibit contact.','original'),
('127.750.d.10.B.iii',3,'An officer arrests a person who violates the terms of a protective order and records details for the report. This is:','["enforcing protective orders in family violence cases", "closing the case", "encouraging violation", "ignoring the order"]'::jsonb,0,'Violations can lead to arrest.','original'),
('127.750.d.10.B.iii',4,'If an officer finds that a protective order has been violated, the officer may:','["wait a week", "make an arrest and document the violation", "ignore it", "tell the victim to leave"]'::jsonb,1,'Enforcement is part of the process.','original'),
('127.750.d.11.A',3,'A cadet studies marijuana, methamphetamine, heroin and prescription opioids as current examples of:','["safe medicines in all cases", "school supplies", "commonly abused drugs in society", "common foods"]'::jsonb,2,'Drug types vary.','original'),
('127.750.d.11.A',4,'Which is an example of a commonly abused prescription drug?','["multivitamin", "aspirin only", "vitamin C", "opioid pain medication"]'::jsonb,3,'Opioids are widely misused.','original'),
('127.750.d.11.B',3,'A cadet reads the Texas Health and Safety Code to learn which penalty group a drug is in. This is researching:','["the effects of substances under Texas law", "tax rules", "school rules", "parking rules"]'::jsonb,0,'The code classifies controlled substances.','original'),
('127.750.d.11.B',4,'The Texas Controlled Substances Act sorts drugs into:','["colors", "penalty groups based on their potential for harm", "flavors", "brands"]'::jsonb,1,'Penalty groups guide charges.','original'),
('127.750.d.11.C',3,'An officer finds pills during a search, records where they were found, packages them and logs them as evidence. This follows:','["no procedures", "random handling", "procedures for handling drugs and controlled substances", "tossing it"]'::jsonb,2,'Handling procedures protect the chain of custody.','original'),
('127.750.d.11.C',4,'When seizing suspected drugs, an officer must be careful to:','["share them", "destroy them on the spot", "use them", "preserve the chain of custody and avoid contamination"]'::jsonb,3,'Evidence integrity is key.','original'),
('127.750.d.12.A',3,'Officers who walk neighborhoods, work with residents and solve problems together are practicing:','["community-oriented policing", "avoiding communities", "rapid response only", "isolated patrol"]'::jsonb,0,'COP builds partnerships.','original'),
('127.750.d.12.A',4,'Community-oriented policing emphasizes:','["only reports", "partnerships between police and citizens to solve problems", "only arrests", "isolation"]'::jsonb,1,'Partnership is the core idea.','original'),
('127.750.d.12.B',3,'A community-oriented officer needs good communication, patience and problem-solving. These are:','["unneeded", "liabilities", "skills needed to be successful in community policing", "hobbies"]'::jsonb,2,'Skills support partnership.','original'),
('127.750.d.12.B',4,'Which skill is most important for a community-oriented police officer?','["working alone", "relying on force", "avoiding residents", "building rapport and communicating with residents"]'::jsonb,3,'Rapport enables cooperation.','original'),
('127.750.d.13.A',3,'A police call sheet lists the time of the call, the location and the nature of the incident, while an incident report adds names and details. These are:','["components of police reports", "jokes", "no records", "random notes"]'::jsonb,0,'Reports contain structured information.','original'),
('127.750.d.13.A',4,'A supplemental report is written to:','["replace the first report", "add new information to an earlier report", "delete the case", "hide the first report"]'::jsonb,1,'Supplements update the record.','original'),
('127.750.d.13.B',3,'Prosecutors, courts and other officers rely on accurate police reports, which is why they are:','["unneeded", "secret", "important for documenting facts and supporting the case", "just paperwork"]'::jsonb,2,'Reports support justice.','original'),
('127.750.d.13.B',4,'Why must a police report be accurate and complete?','["Accuracy is optional", "Nobody reads it", "It will be thrown away", "It may be used in court and in later investigations"]'::jsonb,3,'Reports are legal records.','original'),
('127.750.d.13.C',3,'During a role-play, a cadet asks a complainant who, what, when, where and how, and writes the answers down. This is:','["obtaining the appropriate information for reports", "guessing", "avoiding questions", "ignoring details"]'::jsonb,0,'Questions gather facts.','original'),
('127.750.d.13.C',4,'Which questions help an officer gather the basic facts for a report?','["why not, maybe, always", "who, what, when, where and how", "paint, draw, color", "wish, hope, guess"]'::jsonb,1,'The 5 W''s and H cover the basics.','original'),
('127.750.d.13.D',3,'A cadet writes a report using correct grammar, proper punctuation and a clear order of events. This is:','["sloppy writing", "avoiding writing", "writing a police report using proper English", "slang writing"]'::jsonb,2,'Clear writing is required.','original'),
('127.750.d.13.D',4,'A well-written police report should be:','["disorganized", "vague", "opinionated", "factual, objective and in correct chronological order"]'::jsonb,3,'Reports must be clear.','original'),
('127.750.d.14.A',3,'Before stopping a car, an officer considers the location, the time of day and any warning signs about the driver. This is:','["applying techniques to assess risk in vehicle stops", "guessing", "hurrying", "ignoring risk"]'::jsonb,0,'Risk assessment improves safety.','original'),
('127.750.d.14.A',4,'One technique to reduce risk when making a vehicle stop is to:','["turn off lights", "choose a safe, well-lit location when possible", "stop in traffic", "stop anywhere"]'::jsonb,1,'Location affects safety.','original'),
('127.750.d.14.B',3,'An officer studies the Texas Transportation Code sections on speed limits, stop signs and right of way. This is:','["guessing", "ignoring laws", "understanding and analyzing traffic laws", "avoiding study"]'::jsonb,2,'Officers must know the code.','original'),
('127.750.d.14.B',4,'Officers must understand traffic law so that they can:','["skip training", "write random tickets", "avoid stops", "tell whether a violation has occurred before making a stop"]'::jsonb,3,'Knowledge supports lawful stops.','original'),
('127.750.d.14.C',3,'In a simulation, an officer follows a seven-step process to contact a driver at a routine traffic stop for a misdemeanor violation. This is a:','["simulated misdemeanor traffic stop", "parking check", "felony takedown", "patrol shift briefing"]'::jsonb,0,'A set process guides routine stops.','original'),
('127.750.d.14.C',4,'A routine misdemeanor traffic stop generally ends with:','["a trial", "a citation or warning", "a prison sentence", "a court order"]'::jsonb,1,'Typical outcome: citation or warning.','original'),
('127.750.d.14.D',3,'Two patrol units coordinate a high-risk stop of a vehicle linked to a felony, using commands and cover positions. This is a:','["routine stop", "parking check", "simulated felony traffic stop", "traffic count"]'::jsonb,2,'Felony stops use tactics and cover.','original'),
('127.750.d.14.D',4,'A felony traffic stop typically uses more officers than a routine stop because:','["it is cheaper", "it is required for parking", "it is faster", "the risk of a dangerous suspect is higher"]'::jsonb,3,'Added risk calls for added resources.','original'),
('127.750.d.14.E',3,'An officer clocks a car going 75 in a 55 zone and checks the Transportation Code. This is:','["identifying that a traffic law has been violated", "guessing", "ignoring facts", "avoiding the code"]'::jsonb,0,'Speeding violates the law.','original'),
('127.750.d.14.E',4,'To decide whether a traffic offense occurred, an officer compares the driver''s action with:','["a rumor", "the text of the Texas Transportation Code", "a menu", "a hunch"]'::jsonb,1,'The code defines offenses.','original'),
('127.750.d.14.F',3,'An officer explains to a driver the notice to appear and options for answering a citation. This covers regulations relating to:','["random procedures", "no regulation", "arrest, charging procedures, notices and processing of traffic offenses", "private deals"]'::jsonb,2,'Procedures are set by law.','original'),
('127.750.d.14.F',4,'When an officer issues a traffic citation, the driver''s signature usually means:','["a payment", "a trial", "a confession", "a promise to appear, not an admission of guilt"]'::jsonb,3,'Signing promises to appear.','original'),
('127.750.d.15.A',3,'At a mock crime scene, a cadet dusts a surface with powder and lifts a fingerprint with tape. This is:','["lifting and preserving developed latent prints", "ignoring prints", "painting", "destroying prints"]'::jsonb,0,'Prints are lifted and preserved.','original'),
('127.750.d.15.A',4,'After lifting a latent print, the cadet should:','["throw it away", "label it with date, location and collector information", "leave it unlabeled", "wipe the surface"]'::jsonb,1,'Labeling maintains the chain of custody.','original'),
('127.750.d.15.B',3,'A cadet photographs a scene from several angles, makes a sketch, collects items and writes notes. This is:','["ignoring the scene", "contaminating evidence", "processing a crime scene to photograph, sketch, search, collect and document", "destroying the scene"]'::jsonb,2,'Scene work includes documenting everything.','original'),
('127.750.d.15.B',4,'The first thing officers do to protect a crime scene is to:','["move items around", "clean it", "let everyone in", "secure and limit access to the area"]'::jsonb,3,'Securing prevents contamination.','original'),
('127.750.d.16.A',3,'A student studies Texas laws about driving while intoxicated, boating while intoxicated and related offenses. This explains:','["laws related to driving while intoxicated and related offenses", "vehicle sales", "traffic signs only", "parking tickets only"]'::jsonb,0,'DWI laws are part of the Penal Code.','original'),
('127.750.d.16.A',4,'Under Texas law, a person is intoxicated if they have a blood alcohol concentration of:','["0.50 only", "0.08 or more, or lack normal use of mental or physical faculties", "0.00", "0.01"]'::jsonb,1,'Texas defines intoxication two ways.','original'),
('127.750.d.16.B',3,'An officer sees a car weaving across lanes at night and decides there is reason to stop the driver. This is developing:','["no reason", "a rumor", "reasonable suspicion for an intoxicated driver stop", "a hunch"]'::jsonb,2,'Observable behavior can create reasonable suspicion.','original'),
('127.750.d.16.B',4,'Which observation could help establish reasonable suspicion of an intoxicated driver?','["good lane use", "stopping at a light", "a clean car", "weaving, wide turns or erratic speeds"]'::jsonb,3,'Erratic driving is a cue.','original'),
('127.750.d.17.A',3,'Officers approach a house by using cover, avoiding silhouettes and communicating quietly. This describes techniques to:','["safely approach a residence or building", "ignore dangers", "rush in", "avoid training"]'::jsonb,0,'Careful approach improves safety.','original'),
('127.750.d.17.A',4,'When approaching a building where a suspect may be inside, officers should use:','["bright lights", "cover and concealment", "loud noise", "open ground"]'::jsonb,1,'Cover reduces exposure.','original'),
('127.750.d.17.B',3,'Before entering, officers decide who will go first, how they will communicate and how to keep each other covered. This is:','["skipping planning", "random entry", "techniques to safely enter and search a building", "guessing"]'::jsonb,2,'Planning supports safe entry.','original'),
('127.750.d.17.B',4,'Teamwork during a building search is important because officers need to:','["avoid talking", "ignore doors", "work alone", "cover each other and communicate"]'::jsonb,3,'Teamwork improves safety.','original'),
('127.750.d.17.C',3,'In training, a cadet enters a doorway at an angle, checks corners and clears each part of a room in order. This is:','["the correct technique for entering a doorway and searching a room", "unsafe entry", "avoiding rooms", "rushing"]'::jsonb,0,'Systematic searching reduces risk.','original'),
('127.750.d.17.C',4,'When clearing a room, an officer should check:','["only the center", "corners and blind spots in a planned order", "only the door", "only the ceiling"]'::jsonb,1,'Corners hide danger.','original'),
('127.750.d.17.D',3,'Officers clear a house room by room, mark cleared areas and watch for hidden persons. These are:','["methods for cooking", "methods for writing", "methods for clearing buildings or residences", "methods for parking"]'::jsonb,2,'Marking cleared rooms prevents duplication.','original'),
('127.750.d.17.D',4,'After clearing a room, officers often:','["leave it unmarked", "lock it", "go back immediately", "mark it as cleared and move to the next area"]'::jsonb,3,'Marking keeps track.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
